INSERT INTO public.avisos (id,titulo,slug,resumen,cuerpo,categoria_slug,imagen_url,imagen_alt,destacado,publicado,fecha,created_at,updated_at) VALUES ('298e6fee-5e8b-4871-9292-a4ab42c47862','Inscripciones a 1° año: fechas y documentación','inscripciones-primer-anio','Abrimos el período de inscripción para el próximo ciclo lectivo. Conocé la documentación necesaria y los horarios de atención.','La secretaría recibe inscripciones para 1° año en el horario de 8:00 a 16:00 h. Es necesario presentar fotocopia del DNI del estudiante y de un adulto responsable, certificado de estudios primarios en trámite o completo, y libreta sanitaria. El equipo directivo realiza entrevistas informativas con las familias para acompañar la elección de la escuela técnica y explicar la organización del ciclo básico y de las especialidades del ciclo superior.','familias',NULL,NULL,'t','t','2026-08-18','2026-09-01 00:10:00.58179+00','2026-09-01 00:10:00.58179+00') ON CONFLICT DO NOTHING;
INSERT INTO public.avisos (id,titulo,slug,resumen,cuerpo,categoria_slug,imagen_url,imagen_alt,destacado,publicado,fecha,created_at,updated_at) VALUES ('772a0085-dc55-4564-9cc3-f09ded1a7a5c','Muestra anual de proyectos técnicos','muestra-proyectos-tecnicos','Los grupos de 6° y 7° año presentan sus proyectos finales de Informática, Electrónica y Alimentos ante la comunidad educativa.','Durante la jornada, cada equipo expone el proceso completo de su proyecto: relevamiento, diseño, construcción y puesta en funcionamiento. Es una oportunidad para que las familias y las escuelas primarias del distrito conozcan de primera mano el trabajo real que se produce en los talleres y laboratorios de la escuela.','institucionales',NULL,NULL,'t','t','2026-08-11','2026-09-01 00:10:00.737687+00','2026-09-01 00:10:00.737687+00') ON CONFLICT DO NOTHING;
INSERT INTO public.avisos (id,titulo,slug,resumen,cuerpo,categoria_slug,imagen_url,imagen_alt,destacado,publicado,fecha,created_at,updated_at) VALUES ('e9b82afe-6473-47fb-9e79-1ff750e48396','Elecciones del Centro de Estudiantes','eleccion-centro-estudiantes','Se presentan las listas y se define el cronograma de campaña y votación para la nueva conducción estudiantil.','La participación estudiantil es parte de la formación ciudadana de la escuela. Las listas pueden presentar su propuesta ante la junta electoral estudiantil, con el acompañamiento del equipo de preceptores y del área de orientación.','centro-estudiantes',NULL,NULL,'f','t','2026-08-05','2026-09-01 00:10:00.889823+00','2026-09-01 00:10:00.889823+00') ON CONFLICT DO NOTHING;
INSERT INTO public.avisos (id,titulo,slug,resumen,cuerpo,categoria_slug,imagen_url,imagen_alt,destacado,publicado,fecha,created_at,updated_at) VALUES ('e82e23b9-e5e2-44a9-95ab-984c1cfd3ded','Entrega de boletines y reunión por curso','entrega-boletines','Cada preceptoría comunica el horario de entrega de boletines y de la reunión con las familias.','Pedimos a las familias asistir con la libreta de comunicaciones. En la reunión se comparte el estado de las trayectorias escolares y los espacios de apoyo disponibles para acompañar a cada estudiante.','familias',NULL,NULL,'f','t','2026-07-28','2026-09-01 00:10:01.040496+00','2026-09-01 00:10:01.040496+00') ON CONFLICT DO NOTHING;
INSERT INTO public.avisos (id,titulo,slug,resumen,cuerpo,categoria_slug,imagen_url,imagen_alt,destacado,publicado,fecha,created_at,updated_at) VALUES ('69c5f53f-90af-4317-9759-3436b3da5b71','Prácticas profesionalizantes 2026','practicas-profesionalizantes','Estudiantes de 7° año inician sus prácticas en empresas e instituciones del distrito.','Las prácticas profesionalizantes son el último tramo de la formación técnica y ponen en juego los saberes del taller en contextos reales de trabajo, con seguimiento de docentes tutores.','institucionales',NULL,NULL,'f','t','2026-07-15','2026-09-01 00:10:01.191198+00','2026-09-01 00:10:01.191198+00') ON CONFLICT DO NOTHING;
